def polynomial_to_string(n, coeffs):
    polynomial_string = ""
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            degree = n - i
            if coeff == 1 and degree > 1:
                poly_str = f"x^{degree}"
            elif coeff == 1 and degree == 1:
                poly_str = "x"
            else:
